    if value is None:
        raise TypeError("Cannot dehydrate None: expected a Point instance")

    # If it's a simple tuple/list with two elements, return a clean tuple of floats
    if isinstance(value, (tuple, list)):
        try:
            if len(value) != 2:
                raise ValueError
            return (float(value[0]), float(value[1]))
        except Exception:
            pass  # fall through to attribute check

    # Attempt to access x and y attributes
    try:
        x = getattr(value, "x")
        y = getattr(value, "y")
        # Convert to floats if possible
        try:
            x = float(x)
            y = float(y)
        except Exception:
            pass
        return (x, y)
    except Exception as exc:
        raise TypeError(f"Unable to dehydrate object {value!r} into a point: {exc}") from exc

