    """
    Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    # Determine which attribute holds the underlying collection.
    collection = None
    if hasattr(self, 'data'):
        collection = getattr(self, 'data')
    elif hasattr(self, 'items'):
        collection = getattr(self, 'items')
    elif hasattr(self, 'list'):
        collection = getattr(self, 'list')
    else:
        # If self itself behaves like a sequence, use it.
        if hasattr(self, '__len__') and hasattr(self, '__getitem__'):
            collection = self
        else:
            raise TypeError("No suitable collection attribute found to search index")

    # Attempt to use the built‑in index method if available.
    try:
        return collection.index(key)
    except AttributeError:
        # collection has no .index method; fall back to manual search.
        pass
    except ValueError:
        # Item not found via .index; raise the same error.
        raise

    # Manual linear search
    for idx, item in enumerate(collection):
        if item == key:
            return idx
    # If we reach here, the key was not found.
    raise ValueError(f"{key!r} is not in collection")

