def values(self, *keys):
    """Return the values of the record, optionally filtering to include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none are provided,
                 all values will be included
    :return: list of values
    :rtype: list
    """
    # Obtain the underlying data mapping.  The exact attribute name may vary,
    # but we will check a few common conventions.
    try:
        data = getattr(self, "data")
    except AttributeError:
        data = getattr(self, "_data", None)
    if data is None:
        raise AttributeError(
            "The record instance does not contain a 'data' or '_data' attribute."
        )
    if not isinstance(data, dict):
        raise TypeError("The record's data attribute must be a dictionary.")
    # If no keys were supplied, return all values preserving insertion order.
    if not keys:
        return list(data.values())
    # Build the list of keys to retrieve.
    ordered_keys = list(data.keys())
    result = []
    for key in keys:
        # Interpret integers as positional indices into the key list.
        if isinstance(key, int):
            try:
                mapped_key = ordered_keys[key]
            except IndexError as exc:
                raise IndexError(f"Index {key} is out of range.") from exc
        else:
            mapped_key = key
            if mapped_key not in data:
                raise KeyError(f"Key {mapped_key!r} not found in the record.")
        result.append(data[mapped_key])
    return result

