def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Helper to locate the storage lists.  Different implementations
    # may use slightly different attribute names.
    def _try_attr(name):
        return getattr(self, name, None)

    # Attempt to find a list of names and a list of values.
    name_list = (_try_attr("keys") if _try_attr("keys") is not None else
                 _try_attr("_keys") if _try_attr("_keys") is not None else
                 _try_attr("field_names") if _try_attr("field_names") is not None else
                 _try_attr("_field_names"))

    value_list = (_try_attr("values") if _try_attr("values") is not None else
                  _try_attr("_values") if _try_attr("_values") is not None else
                  _try_attr("data") if _try_attr("data") is not None else
                  _try_attr("_data"))

    # If we couldn't find the usual attributes, fall back on the
    # instance's public attributes dictionary (excluding private ones).
    if name_list is None or value_list is None or len(name_list) != len(value_list):
        public_attrs = {k: v for k, v in self.__dict__.items() if not k.startswith("_")}
        if not keys:
            return public_attrs
        return {k: public_attrs.get(k, None) for k in keys}

    # All normal operations below use name_list/value_list.
    if not keys:
        return dict(zip(name_list, value_list))

    # Map name to index for quick lookup
    name_to_index = {name: idx for idx, name in enumerate(name_list)}

    result = {}
    for k in keys:
        if isinstance(k, int):
            if k < 0 or k >= len(value_list):
                raise IndexError(f"Index out of bounds: {k}")
            name = name_list[k]
            result[name] = value_list[k]
        else:
            # treat as field name
            if k in name_to_index:
                result[k] = value_list[name_to_index[k]]
            else:
