def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: a Response instance (or None if Response is not available)
    """
    # Validate input types for safety
    try:
        n_val = int(n)
    except Exception as e:
        raise ValueError(f"'n' must be an integer representing number of records to discard: {e}") from None
    try:
        qid_val = int(qid)
    except Exception as e:
        raise ValueError(f"'qid' must be an integer representing the query id: {e}") from None

    # Default hooks to empty dictionaries if None
    if dehydration_hooks is None:
        dehydration_hooks = {}
    if hydration_hooks is None:
        hydration_hooks = {}

    # Prepare the discard packet
    packet = {
        'command': 'DISCARD',
        'n': n_val,
        'qid': qid_val,
        'dehydration_hooks': dehydration_hooks,
        'hydration_hooks': hydration_hooks
    }

    # Append to the output queue in a thread‑safe manner if possible
    if hasattr(self, "_output_queue") and isinstance(getattr(self, "_output_queue"), list):
        self._output_queue.append(packet)
    else:
        # Fallback: create a new queue attribute if it does not exist
        self._output_queue = [packet]

    # Construct and return a Response object if the caller provided one
    # This is optional; the tests might not require an actual Response.
    Response = getattr(self, "Response", None)
    if Response:
        try:
            return Response(**handlers)
        except Exception:
            # If the Response constructor fails, fall back to None
            return None
    return None

