        if timeout is not None:
            payload['timeout'] = timeout
        if db is not None:
            payload['db'] = db
        if imp_user is not None:
            payload['imp_user'] = imp_user
        if dehydration_hooks is not None:
            payload['dehydration_hooks'] = dehydration_hooks
        if hydration_hooks is not None:
            payload['hydration_hooks'] = hydration_hooks

        # Append the BEGIN message to the output queue
        # The queue attribute may have different names; fall back to a generic list
        queue_attr = None
        for attr in ("_queue", "_output_queue", "_command_queue", "queue"):
            if hasattr(self, attr):
