def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    Parameters
    ----------
    cache : mapping or object with __getitem__ / __setitem__ / get
        Cache storage where computed values will be stored.
    key : callable, optional
        Function that accepts the same arguments as the decorated method
        and returns a hashable cache key. Defaults to :func:`hashkey`
        which is expected to be defined elsewhere.
    lock : context manager, optional
        An optional lock that will be acquired around cache reads/writes
        to provide thread safety.

    Returns
    -------
    decorator : callable
        A decorator that memoizes the wrapped function.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            # 1. Compute cache key
            try:
                cache_key = key(*args, **kwargs)
            except Exception:
                # Fallback: simple tuple of args and sorted kwargs
                cache_key = (args, tuple(sorted(kwargs.items())))

            # 2. Attempt to read from cache
            cached_val = None
            if lock:
                with lock:
                    if hasattr(cache, "get"):
                        cached_val = cache.get(cache_key)
                    else:
                        # fallback to direct item access with KeyError guard
                        try:
                            cached_val = cache[cache_key]
                        except Exception:
                            cached_val = None
                if cached_val is not None:
                    return cached_val
            else:
                if hasattr(cache, "get"):
                    cached_val = cache.get(cache_key)
                else:
                    try:
                        cached_val = cache[cache_key]
                    except Exception:
                        cached_val = None
                if cached_val is not None:
                    return cached_val

            # 3. Compute the real value
            result = func(*args, **kwargs)

            # 4. Store in cache
            if lock:
                with lock:
                    if hasattr(cache, "__setitem__"):
                        cache[cache_key] = result
            else:
                if hasattr(cache, "__setitem__"):
                    cache[cache_key] = result

            return result

        # Preserve basic metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__dict__.update(func.__dict__)
        return wrapper
    return decorator

