def _legacy_mergeOrderings(orderings):
    """
    Merge multiple orderings so that within-ordering order is preserved.

    Parameters
    ----------
    orderings : list[list]
        A list of orderings. Within each ordering, the relative order of elements must be
        preserved in the final result. It is assumed that if an element appears in more
        than one ordering, then the suffix starting from that element is identical in
        all those orderings.

    Returns
    -------
    list
        A merged ordering that preserves all internal ordering constraints.

    Raises
    ------
    ValueError
        If the input orderings contain a cycle (i.e. conflicting ordering constraints).
    """
    # Build adjacency list and indegree counts
    graph = {}
    indegree = {}

    # Record first appearance order of each unique element
    rank = {}
    order_index = 0
    for ordering in orderings:
        for elem in ordering:
            if elem not in rank:
                rank[elem] = order_index
                order_index += 1
            # initialise nodes in graph and indegree
            if elem not in graph:
                graph[elem] = set()
            if elem not in indegree:
                indegree[elem] = 0

    # Add edges from each ordering
    for ordering in orderings:
        for a, b in zip(ordering, ordering[1:]):
            if b not in graph[a]:
                graph[a].add(b)
                indegree[b] = indegree.get(b, 0) + 1

    # Use Kahn's algorithm with deterministic ordering based on first appearance
    import heapq
    zero_indeg_heap = []
    for node, deg in indegree.items():
        if deg == 0:
            heapq.heappush(zero_indeg_heap, (rank[node], node))

    result = []
    while zero_indeg_heap:
        _, node = heapq.heappop(zero_indeg_heap)
        result.append(node)
        for nb in graph.get(node, ()):
            indegree[nb] -= 1
            if indegree[nb] == 0:
                heapq.heappush(zero_indeg_heap, (rank[nb], nb))

    # Check for cycles
    if len(result) != len(indegree):
        raise ValueError("Cycle detected in ordering constraints")

    return result

