def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        # Determine which classes are not superclasses of any other class in the list
        kept = []
        # We precompute a set of classes to avoid repeated issubclass checks
        class_list = [c for c in classes if isinstance(c, type)]
        for c in classes:
            if not isinstance(c, type):
                # Non-type objects are kept as-is
                kept.append(c)
                continue
            redundant = False
            for other in class_list:
                if other is c:
                    continue
                try:
                    if issubclass(other, c):
                        # c is a superclass of another class, so it's redundant
                        redundant = True
                        break
                except Exception:
                    # If issubclass fails (unlikely for types), ignore and treat as not redundant
                    continue
            if not redundant:
                kept.append(c)
        return kept
    except Exception:
        # In case of unexpected errors, return an empty list as a safe fallback
        return []

