def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both arguments must be dictionaries")

    def _diffsub(a, b, cur_level):
        """Internal recursive helper."""
        # If recursion level is 0, stop recursing
        if cur_level == 0:
            return {}
        result = {}
        for key, val_a in a.items():
            if key not in b:
                # If the value is a dict, we can include the reference directly
                # to avoid unnecessary deep copies.
                result[key] = val_a
            else:
                val_b = b[key]
                if isinstance(val_a, dict) and isinstance(val_b, dict):
                    # Recurse with decremented level unless infinite recursion
                    next_level = cur_level - 1 if cur_level > 0 else cur_level
                    sub = _diffsub(val_a, val_b, next_level)
                    if sub:
                        result[key] = sub
                else:
                    # For level 1 or deeper, include if values differ
                    if val_a != val_b:
                        result[key] = val_a
        return result

    # Handle infinite recursion separately to avoid needless level checks
    if level == -1:
        # Infinite recursion: continue until no more differences
        def _inf_sub(a, b):
            diff = {}
            for key, val in a.items():
                if key not in b:
                    diff[key] = val
                else:
                    val2 = b[key]
                    if isinstance(val, dict) and isinstance(val2, dict):
                        sub = _inf_sub(val, val2)
                        if sub:
                            diff[key] = sub
                    elif val != val2:
                        diff[key] = val
            return diff

        return _inf_sub(d1, d2)
    else:
        # Ensure level is non-negative; negative values other than -1 are treated as 0
        if level < 0:
            level = 0
        return _diffsub(d1, d2, level)

