def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Ensure required attributes exist
    try:
        edges = getattr(self, 'edges')
        histogram = getattr(self, 'data')
    except AttributeError as exc:
        raise AttributeError("Histogram object must have 'edges' and 'data' attributes.") from exc

    # Validate coordinate
    if not isinstance(coord, (list, tuple, np.ndarray)):
        raise TypeError("coord must be an iterable of coordinate values.")
    if len(coord) != len(edges):
        raise ValueError(f"Expected {len(edges)} coordinate values, got {len(coord)}.")

    # Find bin indices for each dimension
    bins = []
    for dim, (edge, val) in enumerate(zip(edges, coord)):
        # Search for the bin that val belongs to
        try:
            idx = np.searchsorted(edge, val, side='right') - 1
        except Exception as exc:
            raise ValueError(f"Failed to locate bin for dimension {dim} with value {val}.") from exc

        # Check if index is within valid range
        if idx < 0 or idx >= len(edge) - 1:
            # Outside histogram bounds; ignore fill
            return
        bins.append(idx)

    # Increment the histogram bin by the weight
    try:
        histogram[tuple(bins)] += weight
    except TypeError:
        raise TypeError("Weight must be a numeric type.")
    except Exception as exc:
        raise RuntimeError("Failed to update histogram bin.") from exc

    # The method does not return a value (fills in-place).

