def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    The function returns a dictionary mapping ``apiVersion.kind`` identifiers to a
    minimal JSON schema (status, spec, metadata). If an entry exists in
    ``app.spec.observer_schema`` with the same ``kind`` it is ignored.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: A mapping from ``apiVersion.kind`` to a generated default schema.
    """
    # Validate input
    if app is None:
        raise ValueError("app must not be None")

    # Extract manifest and existing observer schema configuration
    try:
        manifest = getattr(app.spec, "manifest", None)
    except AttributeError:
        manifest = None

    if not isinstance(manifest, list):
        # Nothing to process if manifest is not a list
        return {}

    # Gather kinds that already have custom observer schemas
    custom_kinds = set()
    try:
        existing_schemas = getattr(app.spec, "observer_schema", [])
        if isinstance(existing_schemas, list):
            for entry in existing_schemas:
                if isinstance(entry, dict):
                    kind = entry.get("kind") or entry.get("resource")
                    if kind:
                        custom_kinds.add(kind)
    except AttributeError:
        pass

    default_schemas = {}

    for item in manifest:
        if not isinstance(item, dict):
            # Skip invalid entries
            continue
        kind = item.get("kind")
        api_version = item.get("apiVersion")
        if not kind or not api_version:
            # Skip entries that are missing key fields
            continue

        # Skip if a custom schema is already defined for this kind
        if kind in custom_kinds:
            continue

        key = f"{api_version}:{kind}"
        # Construct a minimal JSON schema for the resource
        schema = {
            "type": "object",
            "properties": {
                "metadata": {"type": "object"},
                "spec": {"type": "object"},
                "status": {"type": "object"},
            },
            "additionalProperties": True,
        }
        default_schemas[key] = schema

    return default_schemas

