def formatmany(
        self,
        sql: AnyStr,
        many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
    ) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
        """Convert the SQL query to use the out-style parameters instead of the
        in-style parameters.

        *sql* (:class:`str` or :class:`bytes`) is the SQL query.

        *many_params* (:class:`~collections.abc.Iterable`) contains each set
        of in-style parameters (*params*).

        -   *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
            contains the set of in-style parameters. It maps each parameter
            (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
            is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
            If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
            *params* must be a :class:`~collections.abc.Sequence`.

        Returns a :class:`tuple` containing:

        -   The formatted SQL query (:class:`str` or :class:`bytes`).

        -   A :class:`list` containing each set of converted out-style
            parameters (:class:`dict` or :class:`list`).
        """
        # Ensure sql is of correct type
        is_bytes = isinstance(sql, bytes)
        if is_bytes:
            try:
                sql_text = sql.decode('utf-8')
            except Exception as exc:
                raise ValueError("Provided sql bytes could not be decoded as UTF-8") from exc
        else:
            sql_text = str(sql)

        # Determine placeholder names for named styles
        placeholder_names = []
        if getattr(self.SQLParams, "in_style", None) == "named":
            i = 0
            while i < len(sql_text):
                if sql_text[i] == ":":
                    # Start of placeholder
                    j = i + 1
                    # Collect characters that are valid for identifier
                    while j < len(sql_text) and (
                        sql_text[j].isalnum() or sql_text[j] == "_" or sql_text[j] == "$"
                    ):
                        j += 1
                    if j > i + 1:
                        placeholder_names.append(sql_text[i + 1 : j])
                        i = j
                        continue
                i += 1

        out_style = getattr(self.SQLParams, "out_style", None)
        in_style = getattr(self.SQLParams, "in_style", None)

        # Prepare result container
        converted_params_list = []

        # Helper to check mapping param
        def _check_mapping(params):
            if not isinstance(params, dict):
                raise TypeError(
                    f"Expected mapping for named parameters, got {type(params).__name__}"
                )

        # Helper to check sequence param
        def _check_sequence(params):
            if isinstance(params, (str, bytes)):
                raise TypeError(
                    f"Expected sequence for ordinal parameters, got {type(params).__name__}"
                )
            if not hasattr(params, "__iter__"):
                raise TypeError(
                    f"Expected iterable for ordinal parameters, got {type(params).__name__}"
                )

        for idx, params in enumerate(many_params):
            # Validate param type based on in_style
            if in_style == "named":
                _check_mapping(params)
            else:  # ordinal
                _check_sequence(params)

            # Convert based on out_style
            if out_style == "named":
                if in_style == "named":
                    # Already named, but ensure all placeholders present
                    if set(params.keys()) != set(placeholder_names):
                        missing = set(placeholder_names) - set(params.keys())
                        extra = set(params.keys()) - set(placeholder_names)
                        raise KeyError(
                            f"Parameter mismatch for statement {idx}. "
                            f"Missing: {missing}. Extra: {extra}."
                        )
                    converted_params_list.append(params)
                else:
                    # In ordinal form, need to create mapping with placeholder names
                    if not placeholder_names:
                        raise ValueError(
                            f"No placeholder names extracted for ordinal input at index {idx}"
                        )
                    if len(params) != len(placeholder_names):
                        raise ValueError(
                            f"Parameter count mismatch for statement {idx}: "
                            f"expected {len(placeholder_names)}, got {len(params)}."
                        )
                    # Build dictionary
                    converted_params_list.append(
                        {name: val for name, val in zip(placeholder_names, params)}
                    )
            else:  # out_style == "ordinal"
                if in_style == "ordinal":
                    # Already ordinal, ensure it's a list or tuple
                    converted_params_list.append(list(params))
                else:
                    # Convert mapping to ordered list based on placeholder names
                    if not placeholder_names:
                        raise ValueError(
                            f"No placeholder names extracted for named input at index {idx}"
                        )
                    # Build list in placeholder order
                    try:
                        ordered = [params[name] for name in placeholder_names]
                    except KeyError as e:
                        raise KeyError(
                            f"Missing key {e.args[0]} in parameters for statement {idx}"
                        ) from None
                    converted_params_list.append(ordered)

        # Reconstruct SQL in original type
        out_sql = sql_text.encode("utf-8") if is_bytes else sql_text

        return out_sql, converted_params_list

