def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    import os
    import json

    try:
        # Normalize the path
        if hasattr(path, "join"):
            # Path-like objects
            path_str = os.fspath(path)
        else:
            path_str = str(path)

        if not os.path.exists(path_str):
            return False

        # Check if this is a repository root
        repo_json = os.path.join(path_str, ".ocfl", "repository.json")
        if os.path.isfile(repo_json):
            try:
                with open(repo_json, "r", encoding="utf-8") as fh:
                    repo_data = json.load(fh)
            except Exception:
                return False
            # Basic sanity check for required fields
            if repo_data.get("ocflVersion") not in ("1.0", "2.0"):
                return False
            # Repository json valid
            return True

        # Otherwise, check if this is an object root
        manifest_json = os.path.join(path_str, "manifest.json")
        if os.path.isfile(manifest_json):
            try:
                with open(manifest_json, "r", encoding="utf-8") as fh:
                    object_data = json.load(fh)
            except Exception:
                return False
            # Basic sanity: must contain a "state" field
            if not isinstance(object_data.get("state"), dict):
                return False
            # Accept missing payload files as warning
            return True

        # If neither repository nor object is detected, invalid
        return False

    except Exception:
        # Any unforeseen error treated as invalid
        return False

