def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic inventory sanity check
    if inventory is None or not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")

    # -------------------------------------------------
    # Determine spec_version if requested
    # -------------------------------------------------
    if extract_spec_version:
        # Prefer a type key that indicates the spec version
        type_val = inventory.get("type")
        if isinstance(type_val, str):
            # Accept common patterns like 'spec-v1', 'inventory-2', etc.
            try:
                # pick last numeric segment
                spec_ver = int([seg for seg in type_val.split() if seg.isdigit()][-1])
                self.spec_version = spec_ver
            except Exception:
                # fall back to None if we cannot guess
                pass

        # If we didn't get a spec_version from type, look for an explicit key
        if not hasattr(self, "spec_version") or self.spec_version is None:
            if "spec_version" in inventory:
                try:
                    self.spec_version = int(inventory["spec_version"])
                except Exception:
                    pass
            elif "version" in inventory:
                try:
                    self.spec_version = int(inventory["version"])
                except Exception:
                    pass

        # Final fallback: an attribute already set on the instance
        if not hasattr(self, "spec_version") or self.spec_version is None:
            # keep whatever value (could be None) and let the checks below fail
            pass

    # -------------------------------------------------
    # Ensure we have a spec_version to work with
    # -------------------------------------------------
    if not hasattr(self, "spec_version") or self.spec_version is None:
        raise ValueError("spec_version must be set either in the instance or by extraction")

    # -------------------------------------------------
    # Run version‑specific checks
    # -------------------------------------------------
    # For illustrative purposes, we assume two versions:
    # 1 – must contain a 'components' list
    # 2 – must contain an 'assets' dict
    if self.spec_version == 1:
        comps = inventory.get("components")
        if comps is None:
            raise ValueError("Spec version 1 inventory must have a 'components' key")
        if not isinstance(comps, list):
            raise TypeError("'components' must be a list")
        for comp in comps:
            if not isinstance(comp, dict):
                raise TypeError("Each component must be a dict")
    elif self.spec_version == 2:
        assets = inventory.get("assets")
        if assets is None:
            raise ValueError("Spec version 2 inventory must have an 'assets' key")
        if not isinstance(assets, dict):
            raise TypeError("'assets' must be a dict")
        # Optional: ensure each asset entry is a dict
        for key, value in assets.items():
            if not isinstance(value, dict):
                raise TypeError(f"Asset entry for key '{key}' must be a dict")
    else:
        # Unsupported version: prevent accidental pass
        raise ValueError(f"Unsupported spec_version: {self.spec_version}")

    # If we reach here, the inventory passed all checks
    return True

