def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is of the same type
    if not isinstance(prior, self.__class__):
        raise TypeError(
            f"prior must be an instance of {self.__class__.__name__}, "
            f"got {type(prior).__name__}"
        )

    # Attempt to obtain the version indicators from both objects.
    # Support common attribute names that might be used.
    def _get_version(obj):
        for attr in ("version_number", "version", "index", "version_index"):
            if hasattr(obj, attr):
                return getattr(obj, attr)
        raise AttributeError(
            f"Could not find a version attribute on {obj.__class__.__name__}"
        )

    self_version = _get_version(self)
    prior_version = _get_version(prior)

    # If either version is None we cannot compare.
    if self_version is None or prior_version is None:
        raise ValueError("Version attribute is None; cannot compare versions.")

    # Try numeric comparison if both are numbers; otherwise fall back to string comparison.
    try:
        if isinstance(self_version, (int, float)) and isinstance(prior_version, (int, float)):
            if prior_version > self_version:
                raise ValueError(
                    f"Prior inventory {prior_version} is newer than the current inventory {self_version}."
                )
        else:
            if str(prior_version) > str(self_version):
                raise ValueError(
                    f"Prior inventory version {prior_version} is newer than the current inventory {self_version}."
                )
    except TypeError as exc:
        raise ValueError(
            f"Cannot compare inventory versions: {self_version!r} vs {prior_version!r}"
        ) from exc

    # If no exception was raised, the prior inventory is considered valid
    return True

