def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate input
    if not isinstance(inventory, (dict, list)):
        raise TypeError("inventory must be a dict or list")
    if not isinstance(version, str):
        # try to convert to str
        try:
            version = str(version)
        except Exception:
            raise TypeError("version must be a string or convertible to string")

    # Helper to extract keys with flexible naming
    def _get_key(d, keys):
        for k in keys:
            if k in d:
                return d[k]
        return None

    # Gather entries
    entries = []
    if isinstance(inventory, list):
        entries = inventory
    elif isinstance(inventory, dict):
        # Common container names
        for container_name in ('states', 'entries', 'items', 'data', 'logs'):
            if container_name in inventory:
                container = inventory[container_name]
                if isinstance(container, list):
                    entries = container
                    break
        else:
            # If inventory itself looks like an entry
            if any(isinstance(v, dict) for v in inventory.values()):
                entries = list(inventory.values())
            else:
                entries = []

    # First pass: find logical paths present in the requested version
    logical_paths_in_version = set()
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        entry_version = _get_key(entry, ('version', 'ver', 'state_version'))
        if entry_version is None:
            continue
        if entry_version == version:
            path = _get_key(entry, ('logical_path', 'logicalPath', 'path', 'log_path'))
            if isinstance(path, str):
                logical_paths_in_version.add(path)

    # Second pass: map logical paths to all content files across all versions
    result = {}
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        path = _get_key(entry, ('logical_path', 'logicalPath', 'path', 'log_path'))
        if not isinstance(path, str):
            continue
        if path not in logical_paths_in_version:
            continue
        content_file = _get_key(entry, ('content_file', 'contentFile', 'file', 'filename'))
        if content_file is None:
            continue
        # Normalize content_file to str
        try:
            content_file = str(content_file)
        except Exception:
            continue
        result.setdefault(path, set()).add(content_file)

    return result

