def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise ValueError(f"Fixity block must be a dictionary, got {type(fixity).__name__}")

    # Ensure manifest_files is iterate-able and support membership checks
    try:
        if not hasattr(manifest_files, "__contains__"):
            raise TypeError
    except Exception:
        raise ValueError("manifest_files must be a collection supporting membership checks")

    # Each key in the fixity block is expected to be a file path string
    for file_path, file_info in fixity.items():
        if not isinstance(file_path, str):
            raise ValueError(f"Fixity key '{file_path}' is not a string")

        # Only files listed in the manifest may be referenced
        if file_path not in manifest_files:
            raise ValueError(f"Fixity references file '{file_path}' not present in the manifest")

        # The value must contain at least a checksum and an algorithm
        if not isinstance(file_info, dict):
            raise ValueError(f"Information for '{file_path}' must be a dictionary, got {type(file_info).__name__}")

        required_keys = {"checksum", "checksumAlgorithm"}
        missing = required_keys - file_info.keys()
        if missing:
            raise ValueError(f"Missing required keys for '{file_path}': {', '.join(sorted(missing))}")

        # Basic validation of checksum and algorithm types
        if not isinstance(file_info["checksum"], str) or not file_info["checksum"]:
            raise ValueError(f"Checksum for '{file_path}' must be a non-empty string")
        if not isinstance(file_info["checksumAlgorithm"], str) or not file_info["checksumAlgorithm"]:
            raise ValueError(f"Checksum algorithm for '{file_path}' must be a non-empty string")

    # If all checks pass, return True for convenience
    return True

