def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import zipfile
    from pathlib import Path

    if not isinstance(zip_path, str):
        raise TypeError("zip_path must be a string path")

    try:
        zf = zipfile.ZipFile(zip_path, 'r')
    except (FileNotFoundError, zipfile.BadZipFile) as exc:
        raise ValueError(f"Unable to read zip file '{zip_path}': {exc}") from exc

    result = {}
    try:
        for entry in zf.infolist():
            if entry.is_dir():
                continue
            rel_path = Path(entry.filename)
            base = rel_path.stem
            if base not in result:
                result[base] = {}
            # Read file content only for XML files
            if rel_path.suffix.lower() == ".xml":
                try:
                    with zf.open(entry, 'r') as f:
                        raw = f.read()
                    content = raw.decode('utf-8', errors='ignore')
                except Exception:
                    content = None
                result[base]['xml'] = content
            else:
                result[base].setdefault('files', []).append(str(rel_path))
    finally:
        zf.close()
    return result

