def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    import re
    if issue is None:
        return (None, None)
    # Try to get text content
    text = None
    try:
        text = issue.text if hasattr(issue, "text") else str(issue)
    except Exception:
        return (None, None)
    if not isinstance(text, str):
        return (None, None)
    text = text.strip()
    if not text:
        return (None, None)
    # Normalise whitespace
    text = re.sub(r'\s+', ' ', text)
    # Find the first integer as the issue number
    num_match = re.search(r'\d+', text)
    number = int(num_match.group()) if num_match else None

    # Determine if it is a supplement
    suppl_flag = False
    # Suppl / sup / spe patterns (case-insensitive)
    pref = re.compile(r'\b(suppl|supp|supl|spe|s\d?)\.?\b', re.I)
    if pref.search(text):
        suppl_flag = True

    # Extract supplement number if present
    suppl_num = None
    suppl_num_match = re.search(r'(suppl|supp|supl|spe)\s*\.?\s*(\d+)', text, re.I)
    if suppl_num_match:
        try:
            suppl_num = int(suppl_num_match.group(2))
        except Exception:
            suppl_num = None

    # If it's a supplement but no superscript number, we return True
    # Otherwise we return the extracted number (or None)
    if suppl_flag:
        supers = suppl_num

