def on(self, hook):
        """
        Decorator function to add a new handler to the registry.

        Args:
            hook (HookType): Hook attribute for which to register the handler.

        Returns:
            callable: Decorator for registering listeners for the specified
            hook.
        """
        # Validate that the hook is a hashable value and not None.
        if hook is None:
            raise ValueError("hook cannot be None")
        try:
            hash(hook)
        except TypeError:
            raise TypeError("hook must be hashable to be used as a registry key")

        # Prepare the registry storage if it does not exist yet.
        if not hasattr(self, "_registry"):
            self._registry = {}

        # The decorator that registers the function.
        def decorator(func):
            if not callable(func):
                raise TypeError("handler must be a callable object")
            self._registry.setdefault(hook, []).append(func)
            return func

        return decorator.

