def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings.
    """
    if not callable(namefunc):
        raise TypeError("namefunc must be callable")
    def wrapper(*args, **kwargs):
        try:
            result = namefunc(*args, **kwargs)
        except Exception as exc:
            # Propagate any exceptions from the underlying function
            raise
        # If the underlying function returned None, keep it as is
        if result is None:
            return None
        try:
            # Detect the Python version at call time to avoid import at module load
            import sys
            if sys.version_info[0] < 3:
                # Python 2: tzname already returns a byte string
                return result
            # In Python 3: tzname returns a str, we need to convert to bytes
            if isinstance(result, bytes):
                return result
            if isinstance(result, str):
                # Encode the unicode string to a UTF-8 byte string
                return result.encode('utf-8')
            # If the result is of an unexpected type, return it unchanged
            return result
        except Exception as exc:
            # Wrap any unexpected error in a RuntimeError with context
            raise RuntimeError("tzname_in_python2 wrapper failed") from exc
    return wrapper

