def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        # Attempt to retrieve the version from package metadata
        from importlib.metadata import version, PackageNotFoundError
        # Use the top-level package name (first component of __name__)
        pkg_name = __name__.split('.')[0]
        return version(pkg_name)
    except Exception:
        # If anything goes wrong (e.g., package not installed or metadata unavailable), fall back
        return '0.0.0'

