def plus_or_dot(pieces):
    """
    Return a `+` if the supplied collection of pieces does not already contain a `+`,
    otherwise return a `.`.
    """
    try:
        # If pieces is iterable, look for a '+'
        for element in pieces:
            if element == '+':
                return '.'
        return '+'
    except TypeError:
        # pieces is not iterable; treat it as a single element
        return '.' if pieces == '+' else '+'

