def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        import os, hashlib

        # Determine the root path from the object.  It may be stored under
        # ``root_path`` or ``path`` or ``_root_path`` etc.  If none is found,
        # raise a ValueError to help the caller diagnose the problem.
        root = getattr(self, 'root_path', None) or getattr(self, 'path', None) or getattr(self, '_root_path', None)
        if not root:
            raise ValueError("No storage root path defined on self.")

        if not os.path.isdir(root):
            raise ValueError(f"Specified root path {root!r} is not a directory.")

        num_objects = 0
        good_objects = 0

        for dirpath, dirnames, filenames in os.walk(root):
            # Skip hidden directories unless the caller explicitly wants them.
            # Hidden directories are not generally part of the hierarchy.
            dirnames[:] = [d for d in dirnames if not d.startswith('.')]
            for fname in filenames:
                if fname.startswith('.'):
                    continue  # ignore hidden files
                file_path = os.path.join(dirpath, fname)

                # Validate existence if requested
                if validate_objects:
                    if not os.path.isfile(file_path):
                        if show_warnings:
                            print(f"Warning: {file_path!r} is not a regular file.")
                        continue

                num_objects += 1
                is_good = True

                if check_digests:
                    digest_path = file_path + ".digest"
                    if os.path.isfile(digest_path):
                        try:
                            with open(digest_path, 'r', encoding='utf-8') as f:
                                expected = f.read().strip()
                            if not expected:
                                if show_warnings:
                                    print(f"Warning: empty digest for {file_path!r}.")
                                is_good = False
                            else:
                                md5 = hashlib.md5()
                                with open(file_path, 'rb') as fp:
                                    for chunk in iter(lambda: fp.read(8192), b''):
                                        md5.update(chunk)
                                actual = md5.hexdigest()
                                if actual != expected:
                                    if show_warnings:
                                        print(f"Digest mismatch for {file_path!r}: expected {expected}, got {actual}")
                                    is_good = False
                        except Exception as exc:
                            if show_warnings:
                                print(f"Error verifying digest for {file_path!r}: {exc}")
                            is_good = False
                    else:
                        if show_warnings:
                            print(f"Warning: missing digest file for {file_path!r}.")
                        is_good = False

                if is_good:
                    good_objects += 1

        return num_objects, good_objects

