def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    if parser is None:
        raise TypeError("parser argument cannot be None")
    try:
        actions = getattr(parser, "_actions", None)
    except Exception as exc:
        raise ValueError(f"Unable to access parser actions: {exc}") from exc
    if actions is None:
        raise ValueError("Provided parser object does not support '_actions' attribute")

    flags = []
    for action in actions:
        # Option strings may be empty for positional arguments; skip those
        option_strings = getattr(action, "option_strings", [])
        if option_strings:
            flags.extend(option_strings)

    return " ".join(flags) if flags else ""

