    """
    Deep merge list of (ScalarNode key, Node value) tuples where duplicate keys
    whose values are MappingNode instances are recursively merged. For duplicate
    keys with non-MappingNode values, the last value wins. The function returns
    a new list of tuples with merged content, leaving the original nodes
    unmodified.
    """
    def _merge_mapping_nodes(m1, m2):
        """
        Merge two MappingNode instances. Returns a new MappingNode.
        """
        tag = m1.tag
        # Store existing items in order and mapping from key value to index
        merged_items = []
        key_index = {}
        for k_node, v_node in getattr(m1, 'value', []):
            key_val = getattr(k_node, 'value', None)
            merged_items.append((k_node, v_node))
            key_index[key_val] = len(merged_items) - 1
        for k_node, v_node in getattr(m2, 'value', []):
            key_val = getattr(k_node, 'value', None)
            if key_val in key_index:
                idx = key_index[key_val]
                _, existing_v = merged_items[idx]
                if isinstance(existing_v, MappingNode) and isinstance(v_node, MappingNode):
                    merged_v = _merge_mapping_nodes(existing_v, v_node)
                    merged_items[idx] = (merged_items[idx][0], merged_v)
                else:
