            else:
                merged_items.append((k_node, v_node))
                key_index[key_val] = len(merged_items) - 1
        return MappingNode(tag, merged_items)

    result = []
    key_to_index = {}
    for key_node, value_node in nodes:
        # Use the actual key value; fallback to string representation if missing
        try:
            key_val = key_node.value
        except AttributeError:
            key_val = str(key_node)
        if key_val in key_to_index:
            idx = key_to_index[key_val]
            existing_key_node, existing_value_node = result[idx]
            if isinstance(existing_value_node, MappingNode) and isinstance(value_node, MappingNode):
