def parse_arguments(*arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as an ArgumentParser instance.
    """
    # Import argparse locally to avoid a global import
    try:
        import argparse
    except Exception as import_err:
        raise ImportError("argparse module is required for parsing arguments") from import_err

    # Ensure all arguments are strings
    parsed_args = []
    for arg in arguments:
        if isinstance(arg, str):
            parsed_args.append(arg)
        else:
            try:
                parsed_args.append(str(arg))
            except Exception as e:
                raise ValueError(f"Failed to convert argument {arg!r} to string") from e

    # Create a simple ArgumentParser
    parser = argparse.ArgumentParser()
    # Here we could add specific arguments if needed; for now we parse whatever is provided
    try:
        # parse_args checks sys.argv internally if called without args; we supply our own list
        namespace = parser.parse_args(parsed_args)
    except argparse.ArgumentError as e:
        # This exception is rarely raised by parse_args directly but handle it anyhow
        raise ValueError(f"Argument parsing error: {e}") from e
    except SystemExit as e:
        # parse_args calls sys.exit on failure; catch and raise a more descriptive error
        raise ValueError("Argument parsing failed due to invalid arguments") from e

    return namespace

