def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    try:
        from borgmatic import main
    except Exception:
        # If borgmatic is not importable, return empty string
        return ""

    try:
        import argparse
    except Exception:
        return ""

    # Attempt to obtain the top level parser
    parser = None
    # Common patterns to access the parser in borgmatic
    if hasattr(main, "parser"):
        parser = main.parser
    if parser is None and hasattr(main, "build_parser"):
        try:
            parser = main.build_parser()
        except Exception:
            parser = None
    if parser is None:
        # Try to introspect cli module
        try:
            from borgmatic.cli import run_main
            # run_main has an inner parser
            if hasattr(run_main, "parser"):
                parser = run_main.parser
        except Exception:
            return ""

    if parser is None:
        # Unable to locate parser
        return ""

    # Gather subcommand names and their options
    subcommand_names = []
    subcommand_options = {}

    def recurse(p):
        # If this parser has subparsers, collect the subcommand names
        subparsers_actions = [
            action for action in p._actions
            if isinstance(action, argparse._SubParsersAction)
        ]
        for subparsers_action in subparsers_actions:
            for subcommand, subparser in subparsers_action.choices.items():
                subcommand_names.append(subcommand)
                # Collect options for this subcommand
                opts = []
                for action in subparser._actions:
                    # Include both short and long option strings
                    if action.option_strings:
                        opts.extend(action.option_strings)
                subcommand_options[subcommand] = sorted(opts)
                # Recursively process nested subparsers (if any)
                recurse(subparser)

    recurse(parser)

    # Build the bash completion script
    # Assemble the list of possible subcommands and global options
    global_options = sorted(
        [option for action in parser._actions if action.option_strings for option in action.option_strings]
    )
    script_entries = sorted(set(subcommand_names + global_options))

    # The script will provide completion for the first word (subcommand) and for following words it will provide options
    bash_script = f'''# Bash completion script for borgmatic
_borgmatic() {{
    local cur prev comps
    COMPREPLY=()
    cur="${{COMP_WORDS[COMP_CWORD]}}"
    prev="${{COMP_WORDS[COMP_CWORD-1]}}"
    case "$prev" in
    {'|'.join([sub for sub in subcommand_names])})
        comps='{{" ".join(subcommand_options.get(prev, []))}}'
        ;;
    *)
        comps='{{" ".join(script_entries)}}'
        ;;
    esac
    COMPREPLY=( $(compgen -W "${{comps}}" -- "${{cur}}") )
    return 0
}}
complete -F _borgmatic borgmatic
'''
    return bash_script```

