def split(s, platform='this'):
    """
    Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys
    import shlex

    if platform == 'this':
        platform = 0 if sys.platform.startswith('win') else 1
    if not isinstance(s, (str, bytes)):
        raise TypeError('split() requires a string or bytes.')
    if isinstance(s, bytes):
        # decode using locale or utf-8 as fallback
        try:
            s = s.decode(sys.getfilesystemencoding())
        except Exception:
            s = s.decode('utf-8')

    try:
        if platform == 1:  # POSIX
            return shlex.split(s, posix=True)
        if platform == 0:  # Windows/CMD
            return shlex.split(s, posix=False)
        raise ValueError('Unsupported platform flag')
    except Exception as exc:
        raise ValueError(f'Error splitting command line: {exc}') from exc

