def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        # Use git to list ignored files in the current repository
        output = subprocess.check_output(
            ["git", "ls-files", "-i", "--exclude-standard"],
            stderr=subprocess.STDOUT
        )
    except (subprocess.CalledProcessError, FileNotFoundError):
        # Either git failed to run (not a repo, git not installed, etc.) or returned a non-zero exit status
        return ""
    # Decode bytes to string and split into lines
    decoded = output.decode("utf-8", errors="ignore")
    files = [line.strip() for line in decoded.splitlines() if line.strip()]
    files.sort()
    return ",".join(files)

