def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Basic validation
    try:
        if host is None:
            return False
        host_str = str(host).strip()
        if not host_str:
            return False
    except Exception:
        return False

    try:
        addr_infos = socket.getaddrinfo(host_str, None)
    except (socket.gaierror, OSError):
        return False

    for info in addr_infos:
        family, _, _, _, sockaddr = info
        addr = sockaddr[0]
        try:
            if family == socket.AF_INET:
                # IPv4 loopback
                if addr == "127.0.0.1":
                    return True
                # Check for IPv4-mapped IPv6 on IPv4 socket
                try:
                    packed = socket.inet_aton(addr)
                    if packed[0] == 127:
                        return True
                except Exception:
                    pass
            elif family == socket.AF_INET6:
                # IPv6 loopback
                if addr == "::1":
                    return True
                # IPv6 addresses may be written in full or zero compressed forms
                # Normalize address using inet_pton
                try:
                    packed = socket.inet_pton(socket.AF_INET6, addr)
                    if packed == socket.inet_pton(socket.AF_INET6, "::1"):
                        return True
                except Exception:
                    pass
        except Exception:
            # Any failure to inspect an address should not stop the check
            continue

    return False

