def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    import sys
    # Use safe_dump by default to avoid emitting Python tags
    if dumper is None:
        try:
            yaml_str = yaml.safe_dump(obj, default_flow_style=False)
        except Exception as exc:
            raise ValueError(f"Error dumping object to string: {exc}") from exc
    else:
        try:
            yaml_str = yaml.dump(obj, Dumper=dumper, default_flow_style=False)
        except Exception as exc:
            raise ValueError(f"Error dumping object to string with given Dumper: {exc}") from exc

    # Ensure the return type is unicode in python2 and str in python3
    if sys.version_info[0] < 3:
        # Python 2: try to return a unicode object
        if isinstance(yaml_str, str):
            # `yaml_str` is a byte string; decode to unicode
            try:
                return yaml_str.decode("utf-8")
            except Exception:
                # Fallback to latin-1 for non-utf-8 content
                return yaml_str.decode("latin-1")
        return yaml_str
    else:
        # Python 3: yaml.safe_dump returns a 'str' (unicode) already
        if isinstance(yaml_str, bytes):
            # Rare case: if bytes are returned, decode them
            try:
                return yaml_str.decode("utf-8")
            except Exception:
                return yaml_str.decode("latin-1")
        return yaml_str

