def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple or iterable
        shape of the array to create
    dtype : numpy.dtype or dtype‑compatible object
        data-type of the array to create
    """
    # Validate and normalise the shape
    try:
        if isinstance(shape, (int, np.integer)):
            # Interpret a scalar as a single dimension
            shape_tuple = (int(shape),)
        else:
            shape_tuple = tuple(int(dim) for dim in shape)
    except Exception as exc:
        raise ValueError(f"Invalid shape parameter '{shape!r}'. It must be an iterable of integers.") from exc

    if any(dim <= 0 for dim in shape_tuple):
        raise ValueError(f"All dimensions in shape must be positive. Received: {shape_tuple}")

    # Validate and normalise dtype
    try:
        dtype_obj = np.dtype(dtype)
    except Exception as exc:
        raise TypeError(f"Invalid dtype parameter '{dtype!r}'. It must be a valid NumPy dtype.") from exc

    # Create the array, handling any runtime errors
    try:
        return np.zeros(shape_tuple, dtype=dtype_obj)
    except Exception as exc:
        raise RuntimeError(f"Failed to create an array with shape {shape_tuple} and dtype {dtype_obj}.") from exc

