    def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.
        """
        # Validate that values is iterable
        try:
            iter(values)
        except TypeError:
            raise TypeError("values must be an iterable of strings")

        bookmarks = {}
        for raw in values:
            if not isinstance(raw, str):
                # Skip non-string values
                continue
            raw = raw.strip()
            if not raw:
                # Skip empty strings
                continue

            # Split the raw string into a name and an optional page component.
            # The separator may be a colon, a comma, or even whitespace.
            # We prioritize the first colon as the primary separator.
            if ':' in raw:
                name_part, page_part = raw.split(':', 1)
            elif ',' in raw:
                name_part, page_part = raw.split(',', 1)
            elif raw.isspace():
                # Just whitespace, ignore
                continue
            else:
                name_part, page_part = raw, None

            name = name_part.strip()
            if not name:
                # Skip entries that have no valid name part
                continue

            # Attempt to convert the page part to an integer if possible.
            page = None
            if page_part is not None:
                page_part = page_part.strip()
                if page_part.isdigit() or (
                    page_part.startswith('-') and page_part[1:].isdigit()
                ):
                    try:
                        page = int(page_part)
                    except ValueError:
                        # Fall back to None if conversion fails
                        page = None

            # Store the bookmark; last occurrence wins ties.
            bookmarks[name] = page

        # Delegate to the constructor.
        # The constructor is expected to accept a dict of bookmarks.
        # If the signature differs, this will raise a TypeError, which is
        # appropriate for signaling misuse.
        return cls(bookmarks)

