def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    from collections.abc import Sequence, Iterable

    # If seq is already a sequence (lists, tuples, strings, bytes, etc.)
    if isinstance(seq, Sequence):
        return seq, type(seq)

    # If seq looks like a file-like object (has a read method)
    read_method = getattr(seq, "read", None)
    if callable(read_method):
        # Determine the buffer size to use for the read
        if bufsize is None:
            # Try to use a sensible default; most APIs use 8192 or 8192 bytes
            bufsize = 8192
        try:
            data = seq.read(bufsize)
            return data, type(data)

