def scale(self, other=None, recompute=False):
        """Compute or set scale (integral of the histogram)."""

        # Helper function to find the histogram data attribute
        def _get_data_attr():
            for name in (
                "counts",
                "data",
                "bins",
                "array",
                "values",
                "freqs",
                "hist",
            ):
                if hasattr(self, name):
                    return name, getattr(self, name)
            raise RuntimeError(
                "No histogram data attribute found to compute or rescale the scale."
            )

        # ---------- Retrieve or recompute the scale ----------
        if other is None:
            # Compute if not cached or recompute forced
            if (
                recompute
                or not hasattr(self, "_scale")
                or self._scale is None
            ):
                _, data = _get_data_attr()
                try:
                    total = float(sum(data))
                except Exception as exc:
                    raise RuntimeError("Failed to sum histogram data") from exc
                self._scale = total
            return self._scale

        # ---------- Rescale the histogram ----------
        try:
            new_scale = float(other)
        except Exception as exc:
            raise TypeError("The provided scale must be convertible to float.") from exc

        # Ensure the current scale is available
        current_scale = self.scale(recompute=recompute)

        if current_scale == 0:
            raise LenaValueError(
                "Cannot rescale a histogram with zero scale."
            )

        factor = new_scale / current_scale

        # Modify the underlying histogram data in place
        attr_name, data = _get_data_attr()
        try:
            # Handle standard Python sequences
            if isinstance(data, list):
                for i, val in enumerate(data):
                    data[i] = val * factor
            else:
                # Assume the object supports item assignment
                for i in range(len(data)):
                    data[i] = data[i] * factor
        except Exception:
            # Fallback: rebuild the array and reassign
            try:
                new_data = [val * factor for val in data]
                setattr(self, attr_name, new_data)
            except Exception as exc

