def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Validate inputs
    if not isinstance(bases, (tuple, list)):
        raise TypeError("bases must be an iterable of base classes (tuple or list)")
    if len(bases) == 0:
        # No bases; default to the explicit metaclass or type
        return explicit_mc if explicit_mc is not None else type
    for b in bases:
        if not isinstance(b, type):
            raise TypeError(f"base {b!r} is not a class")
    if explicit_mc is not None and not isinstance(explicit_mc, type):
        raise TypeError(f"explicit metaclass {explicit_mc!r} is not a class")

    # Collect metaclasses from the bases
    metaclasses = [type(b) for b in bases]
    # Include the explicit metaclass if given
    if explicit_mc is not None:
        metaclasses.append(explicit_mc)

    # Determine the most derived metaclass that is a subclass of all the others.
    # The algorithm mirrors CPython's behavior: find a metaclass that is
    # a subclass of every candidate; there should be only one such metaclass.
    chosen = None
    for candidate in metaclasses:
        try:
            # candidate must be a subclass of every metaclass in the list
            if all(issubclass(candidate, m) for m in metaclasses):
                if chosen is not None and chosen != candidate:
                    # conflict: more than one candidate satisfies the rule
                    raise TypeError
                chosen = candidate
        except TypeError:
            # issubclass checks raised TypeError if candidate is not a class
            raise TypeError(f"metaclass conflict: {candidate!r} is not a class")

    if chosen is None:
        # No single metaclass satisfies being a superclass of all others
        # Attempt to find a common ancestor (most derived) among the candidates
        # by looking at the MRO of each metaclass and picking the first one that
        # appears in all MROs.
        common = None
        for candidate in metaclasses:
            mro = candidate.mro()
            if all(candidate in m.mro() for m in metaclasses):
                if common is None:
                    common = candidate
                else:
                    # More than one candidate is a common ancestor; ambiguity
                    common = None
                    break
        if common is not None:
            chosen = common

    if chosen is None:
        metaclass_names = ', '.join([c.__name__ for c in metaclasses])
        raise TypeError(f"metaclass conflict: multiple metaclasses ({metaclass_names})")
    return chosen

