def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    # First attempt to retrieve the value; this determines if key exists
    try:
        value = self[key]
    except KeyError:
        # Key is missing
        if default is __marker:
            # No default supplied – propagate the KeyError
            raise
        else:
            return default
    except TypeError:
        # key is unhashable or otherwise invalid
        # Mimic dict's TypeError message by raising KeyError with key
        raise KeyError(key) from None

    # Key exists; attempt deletion
    try:
        del self[key]
    except Exception as exc:
        # If deletion fails for any reason, raise the exception
        raise

    return value

