def default_tzinfo(dt, tzinfo):
    """
    Sets the ``tzinfo`` parameter on naive datetimes only

    This is useful for example when you are provided a datetime that may have
    either an implicit or explicit time zone, such as when parsing a time zone
    string.
    """
    # Basic type/attribute check: ``dt`` should at least have a ``tzinfo`` attribute
    # and a ``replace`` method, which the standard ``datetime.datetime`` offers.
    if not hasattr(dt, 'tzinfo') or not hasattr(dt, 'replace'):
        raise TypeError("dt must be a datetime.datetime instance")

    # Determine if ``dt`` is naive (no tzinfo set)
    # If ``tzinfo`` is None the check still works because ``None`` is falsy.
    try:
        naive = dt.tzinfo is None
    except Exception as exc:
        raise TypeError("Failed to inspect dt.tzinfo: %s" % exc)

    # If naive, return a new datetime with the supplied tzinfo.
    # ``replace`` does not modify the original instance.
    if naive:
        try:
            return dt.replace(tzinfo=tzinfo)
        except Exception as exc:
            raise ValueError("Unable to set tzinfo on datetime: %s" % exc)

    # If dt is already aware, leave it unchanged.
    return dt

