def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Diaspora request.

    1. Check for a public message: if the request has any of the
       attributes ``public`` or ``is_public`` that evaluates to ``True``.
    2. Check for a private message: if the request has any of
       the attributes ``private`` or ``is_private`` that evaluates
       to ``True``.
    3. Check for a legacy payload: if the request contains keys
       like ``legacy_payload`` or ``legacy`` that look like a
       Diaspora-compatible dictionary, treat it as a Diaspora request.
    4. If none of the above conditions are met, return ``False``.

    The function is defensive: it accepts any object that may provide
    dictionary-like access (via ``get``), attribute access (via ``getattr``),
    or a plain dictionary. Invalid inputs are treated as non-Diaspora
    requests and no exception propagates to the caller.
    """
    try:
        # Helper to get value from dict-like or attribute-like object.
        def _get(name, fallback=None):
            try:
                if isinstance(request, dict):
