def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    Returns the value as an ISO‑8601 string with UTC time zone (`Z` suffix).
    Accepts `datetime.datetime`, `datetime.date`, or a string that can be parsed
    as an ISO‑8601 datetime. If `dt` is `None`, returns an empty string. Raises
    a `TypeError` for unsupported input types.
    """
    # Handle None explicitly
    if dt is None:
        return ''
    # Import datetime only if it hasn't been imported already
    try:
        # Use the caller's datetime module if available
        datetime = datetime  # noqa: F821
    except NameError:
        import datetime  # local import, allowed

    # datetime instance
    if isinstance(dt, datetime.datetime):
        # If naive, assume UTC
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        # Convert to UTC to keep consistent
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.strftime('%Y-%m-%dT%H:%M:%SZ')

    # date instance (no time)
    if isinstance(dt, datetime.date):
        return dt.strftime('%Y-%m-%d')

    # string input – try to parse
    if isinstance(dt, str):
        # Attempt ISO format parsing first
        try:
            parsed = datetime.datetime.fromisoformat(dt)
            return format_dt(parsed)
        except Exception:
            pass
        # Fallback to a common explicit format
        for fmt in ('%Y-%m-%d %H:%M:%S', '%Y-%m-%d'):
            try:
                parsed = datetime.datetime.strptime(dt, fmt)
                return format_dt(parsed)
            except Exception:
                continue
        # If all parsing attempts fail, return the original string
        return dt

    # Unsupported type
    raise TypeError(f'Unsupported type for format_dt: {type(dt).__name__}')

