def find_tags(text: str, replacer: callable = None) -> tuple:
    import re
    # Find all code block ranges (triple backticks)
    code_block_pattern = re.compile(r'```.*?```', re.DOTALL)
    code_blocks = []
    for m in code_block_pattern.finditer(text):
        code_blocks.append((m.start(), m.end()))

    def in_code_block(pos: int) -> bool:
        for start, end in code_blocks:
            if start <= pos < end:
                return True
        return False

    # Tag pattern: words starting with # or @ followed by a word character sequence
    tag_pattern = re.compile(r'(?<!\S)([#@][a-zA-Z_][\w]*)')
    tags = set()
    if replacer:
        parts = []
        last_idx = 0
        for m in tag_pattern.finditer(text):
            if in_code_block(m.start()):
                continue
            tags.add(m.group(0))
            parts.append(text[last_idx:m.start()])
            # Replace tag with replacer's result
            parts.append(str(replacer(m.group(0))))
            last_idx = m.end()
        parts.append(text[last_idx:])
        replaced_text = ''.join(parts)
    else:
        for m in tag_pattern.finditer(text):
            if in_code_block(m.start()):
                continue
            tags.add(m.group(0))
        replaced_text = text

    return tags, replaced_text

