def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    # Ensure the input is a string; otherwise, it cannot be a tag
    if not isinstance(tag, str):
        return False

    # An empty string cannot be a valid tag
    if not tag:
        return False

    # Tags are allowed to contain letters, digits, hyphens, and underscores only
    # No spaces or other punctuation are permitted.
    import re
    pattern = re.compile(r'^[A-Za-z0-9_-]+$')
    return bool(pattern.match(tag))

