def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document or not isinstance(document, str):
        raise ValueError("Input document must be a non-empty string")

    # Helper to strip namespace from tag
    def _strip_ns(tag: str) -> str:
        return tag.split("}", 1)[-1] if "}" in tag else tag

    # Attempt JSON parsing first
    try:
        json_mod = __import__("json")
        data = json_mod.loads(document)
        if not isinstance(data, dict):
            raise ValueError("Parsed JSON is not an object")
        # Normalise keys if necessary
        result = {}
        if "subject" in data:
            result["subject"] = data["subject"]
        if "aliases" in data:
            result["aliases"] = list(data["aliases"])
        else:
            result["aliases"] = []
        if "links" in data and isinstance(data["links"], list):
            result["links"] = data["links"]
        else:
            result["links"] = []
        return result
    except Exception:
        # Not JSON, try XML (XRD)
        try:
            ET = __import__("xml.etree.ElementTree", fromlist=["ElementTree"])
            root = ET.fromstring(document)
        except Exception:
            raise ValueError("Unable to parse document as JSON or XRD")

        subject = None
        aliases = []
        links = []

        for elem in root.iter():
            tag = _strip_ns(elem.tag).lower()
            if tag == "subject" and subject is None:
                subject = elem.text.strip() if elem.text else None
            elif tag == "alias":
                if elem.text:
                    aliases.append(elem.text.strip())
            elif tag == "link":
                attrs = {k: v for k, v in elem.attrib.items()}
                # Ensure required attributes
                if "rel" in attrs and "href" in attrs:
                    links.append(attrs)

        if subject is None:
            raise ValueError("No subject found in XRD document")

        return {"subject": subject, "aliases": aliases, "links": links}

