def list_of_file_names(settings_dirs, spec_option):
    """
    Generate a sorted list of absolute file paths from the provided directories,
    optionally filtered by `spec_option`.

    Parameters
    ----------
    settings_dirs : Iterable[str] or str
        One or more directory paths to search for files. Individual directories
        may be given as strings or path-like objects.

    spec_option : None | str | Callable[[str], bool]
        If ``None``, all files are included.
        If a string containing shell‑style wildcards (``*``, ``?``, ``[]``),
        the filenames are matched using :func:`fnmatch.fnmatch`.
        If a callable, it is applied to the full file path; only those for
        which it returns ``True`` are kept.

    Returns
    -------
    list[str]
        A sorted list of absolute file paths that satisfy the filtering
        criteria. Directories that cannot be read are silently skipped.

    Raises
    ------
    TypeError
        If ``spec_option`` is not ``None``, a string, or a callable.
    """
    import os
    import fnmatch

    # Normalise settings_dirs to an iterable of strings
    if settings_dirs is None:
        return []
    try:
        # Check if it behaves like a string (but not a path)
        if isinstance(settings_dirs, (str, bytes)) or hasattr(settings_dirs, '__fspath__'):
            dirs = [settings_dirs]
        else:
            dirs = list(settings_dirs)
    except Exception:
        dirs = []

    # Define the filtering function
    if spec_option is None:
        def _filter(_path):  # pylint: disable=unused-argument
            return True
    elif isinstance(spec_option, str):
        def _filter(file_path):
            # Match only filename part
            return fnmatch.fnmatch(os.path.basename(file_path), spec_option)
    elif callable(spec_option):
        _filter = spec_option
    else:
        raise TypeError("spec_option must be None, a string, or a callable")

    result_files = []
    for dir_path in dirs:
        try:
            # Resolve path-like objects to strings
            path = os.fspath(dir_path)
        except Exception:
            # Skip entries that cannot be interpreted as a path
            continue

        if not os.path.isdir(path):
            continue

        try:
            for entry in os.listdir(path):
                full_path = os.path.join(path, entry)
                if os.path.isfile(full_path) and _filter(full_path):
                    result_files.append(os.path.abspath(full_path))
        except (OSError, PermissionError):
            # Skip directories that cannot be read
            continue

    return sorted(result_files)

