@classmethod
    def ansible_config_manager(cls):
        """Gets the ansible config manager."""
        try:
            import os
            import configparser
        except Exception as exc:
            raise RuntimeError("Required modules for ansible config manager are missing") from exc

        # Locate the ansible.cfg file
        cfg_path = os.environ.get("ANSIBLE_CONFIG")
        if cfg_path and os.path.isfile(cfg_path):
            path = os.path.abspath(cfg_path)
        else:
            # Check default locations
            home_cfg = os.path.expanduser("~/.ansible.cfg")
            if os.path.isfile(home_cfg):
                path = home_cfg
            else:
                cwd_cfg = os.path.join(os.getcwd(), "ansible.cfg")
                if os.path.isfile(cwd_cfg):
                    path = cwd_cfg
                else:
                    path = None

        # Initialize the config parser
        config = configparser.ConfigParser()

        if path is not None:
            try:
                with open(path, "r", encoding="utf-8") as f:
                    config.read_file(f)
            except Exception as exc:
                raise RuntimeError(f"Failed to read Ansible config file at {path}") from exc
        # If no config file is found, return an empty ConfigParser (uses defaults)
        return config

