def plugins_manager(cls):
    """
    Gets the plugin manager.

    Returns
    -------
    object
        The plugin manager instance associated with the class.

    Notes
    -----
    A minimal in-memory plugin manager is lazily created if one does not
    already exist on the class.  The manager stores plugins in a
    dictionary and provides `register`, `get`, and `all_plugins`
    convenience methods.
    """
    # Ensure a plugin manager instance exists lazily
    if not hasattr(cls, "_plugin_manager") or cls._plugin_manager is None:
        # Define a small default manager if none is provided
        class _DefaultPluginManager:
            def __init__(self):
                self._registry = {}

            def register(self, name, plugin):
                if not isinstance(name, str):
