def get_parser_option_specs(self, command_name):
    """
    Gets all the options for the specified command.

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: a list of dictionaries describing each option for the command.
    """
    if not isinstance(command_name, str) or not command_name.strip():
        raise ValueError("command_name must be a non-empty string")

    # Try to retrieve the parser for the given command.
    # The implementation assumes that the instance has a mapping
    # `_parsers` from command names to parser objects.
    parser = None
    if hasattr(self, "_parsers"):
        parser = self._parsers.get(command_name)
    if parser is None:
        raise KeyError(f"No parser found for command '{command_name}'")

    # If the parser has a custom method to provide option specifications,
    # use it directly.
    if hasattr(parser, "get_option_specs") and callable(parser.get_option_specs):
        try:
            return parser.get_option_specs()
        except Exception as exc:
            raise RuntimeError(
                f"Failed to retrieve option specs from '{command_name}': {exc}"
            ) from exc

    # Fallback to standard argparse processing if the parser follows the
    # conventional API.  An argparse.ArgumentParser exposes the list of
    # actions as `_actions`, each of which contains the option data.
    if not hasattr(parser, "_actions"):
        raise AttributeError(
            f"Parser for command '{command_name}' does not expose expected attributes"
        )
    options = []
    for action in parser._actions:
        # Some actions may be argparse._HelpAction or argparse._VersionAction;
        # they do not correspond to real options and can be skipped.
        if not hasattr(action, "option_strings"):
            continue
        opt = {
            "option_strings": action.option_strings,
            "help": action.help if hasattr(action, "help") else None,
            "required": getattr(action, "required", False),
            "default": getattr(action, "default", None),
            "choices": getattr(action, "choices", None),
            "type": getattr(action, "type", None).__name__
            if getattr(action, "type", None) is not None
            else None,
        }
        options.append(opt)

    return options

