def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    conditionally_required = []
    for opt in options_spec:
        # Support both dicts and objects with attributes
        try:
            if isinstance(opt, dict):
                name = opt.get('name')
                required_when = opt.get('required_when')
            else:
                name = getattr(opt, 'name', None)
                required_when = getattr(opt, 'required_when', None)
        except AttributeError:
            continue

        if not name or not required_when:
            continue

        # Prepare a context for evaluating the condition
        context = {'command_name': command_name}
        context.update(args or {})

        try:
            # If required_when is a callable, call it
            if callable(required_when):
                cond_result = required_when(**context)
            else:
                # Assume it is a string Python expression
                cond_result = eval(required_when, {}, context)
        except Exception:
            # If evaluation fails, treat as not required
            cond_result = False

        if cond_result:
            conditionally_required.append(name)

    return conditionally_required

