def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    The `args` argument can be a mapping or an iterable of values
    with length constraints. It supports the following forms:

    * ``dict`` mapping a key to a ``(value, max_len)`` tuple.
    * ``list``/``tuple`` of ``(value, max_len)`` tuples.
    * Any iterable that yields ``(value, max_len)`` tuples.

    For each pair the method verifies that ``len(value) <= max_len``.
    Non‑contiguous objects that do not support ``len()`` are ignored.
    ``None`` values are considered valid regardless of ``max_len``.

    Raises:
        TypeError: If ``args`` is not a mapping or iterable of pairs.
        ValueError: If a value is longer than the specified maximum length.
    """
    # Helper to validate a single (value, max_len) pair
    def _check_pair(value, max_len, key=None):
        if max_len is None:
            return
        if value is None:
            return
        try:
            length = len(value)
        except Exception as exc:
            raise ValueError(
                f"Cannot determine length of value {value!r} for key {key!r}"
            ) from exc
        if length > max_len:
            raise ValueError(
                f"Value {value!r} for key {key!r} exceeds maximum length "
                f"{max_len} (actual: {length})"
            )

    # If args is a mapping, iterate over items
    if isinstance(args, dict):
        for key, val in args.items():
            if isinstance(val, tuple) and len(val) == 2:
                value, max_len = val
                _check_pair(value, max_len, key)
            else:
                # ignore non‑tuple values silently
                continue
        return

    # Otherwise args should be iterable of (value, max_len) tuples
    try:
        iterator = iter(args)
    except TypeError as exc:
        raise TypeError("args must be a mapping or iterable of tuples") from exc

    for idx, element in enumerate(iterator):
        if not (isinstance(element, tuple) and len(element) == 2):
            # Skip items that are not a (value, max_len) pair
            continue
        value, max_len = element
        _check_pair(value, max_len, f"index {idx}")

