def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """

    # Validate input
    if not plugin_dir:
        raise ValueError("plugin_dir must be a non-empty path string")

    try:
        import os
        import json
    except Exception as exc:
        raise ImportError("Standard library modules required for path handling and JSON parsing are missing") from exc

    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"Plugin directory not found: {plugin_dir}")

    # Supported spec file names
    spec_filenames = ["plugin.json", "plugin.yaml", "plugin.yml"]
    spec_path = None
    for name in spec_filenames:
        path = os.path.join(plugin_dir, name)
        if os.path.isfile(path):
            spec_path = path
            break

    if spec_path is None:
        raise FileNotFoundError(
            f"No plugin spec file found in {plugin_dir}. "
            f"Expected one of: {', '.join(spec_filenames)}"
        )

    # Load spec file
    try:
        if spec_path.endswith(".json"):
            with open(spec_path, "r", encoding="utf-8") as f:
                data = json.load(f)
        else:
            try:
                import yaml
            except ImportError as exc:
                raise ImportError(
                    "yaml module is required to read YAML plugin specs"
                ) from exc
            with open(spec_path, "r", encoding="utf-8") as f:
                data = yaml.safe_load(f)
    except Exception as exc:
        raise ValueError(f"Failed to parse plugin spec file: {spec_path}") from exc

    if not isinstance(data, dict):
        raise ValueError(f"The plugin spec must be a dictionary, got {type(data).__name__}")

    # Helper to flatten nested dictionaries
    flat_dict = {}

    def _flatten(d, parent_key=""):
        for key, value in d.items():
            # Ensure key is a string
            if not isinstance(key, str):
                raise TypeError(f"Plugin spec keys must be strings, got {type(key).__name__}")
            new_key = f"{parent_key}.{key}" if parent_key else key
            if isinstance(value, dict):
                _flatten(value, new_key)
            else:
                flat_dict[new_key] = value

    _flatten(data)

    return flat_dict

