def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    try:
        import os

        # Only set the variable if it is not already defined or is empty
        if not os.environ.get("CONFIG_PATH"):
            # Determine a sensible default path
            try:
                base_dir = os.path.dirname(__file__)  # may fail in interactive sessions
            except NameError:
                base_dir = os.getcwd()
            default_path = os.path.join(base_dir, "config.ini")

            # Fallback to a common system-wide location if the default file does not exist
            if not os.path.exists(default_path):
                default_path = "/etc/app/config.ini"

            os.environ["CONFIG_PATH"] = default_path
    except Exception as exc:  # pragma: no cover
        # In case of an unexpected error, raise a more informative exception
        raise RuntimeError(f"Failed to inject CONFIG_PATH environment variable: {exc}") from exc

